UPDATE "Localities" l
SET "CreatedByUserId" = d."ManagedByUserId",
    "UpdatedAt" = NOW()
FROM "Destinations" d
WHERE l."DestinationId" = d."Id"
  AND d."Name" IN ('Rome', 'Venice', 'Florence', 'Beograd', 'Novi Sad', 'Zlatibor')
  AND d."ManagedByUserId" IS NOT NULL;

