WITH spain_expansion_manager_assignments AS (
    SELECT d."Id" AS destination_id, u."Id" AS manager_id
    FROM (VALUES
        ('Alicante', 'manager.alicante@spirego.com'),
        ('San Sebastian', 'manager.sansebastian@spirego.com'),
        ('Girona', 'manager.girona@spirego.com'),
        ('Cadiz', 'manager.cadiz@spirego.com'),
        ('Murcia', 'manager.murcia@spirego.com'),
        ('Santander', 'manager.santander@spirego.com'),
        ('Tenerife', 'manager.tenerife@spirego.com'),
        ('Santiago de Compostela', 'manager.santiago@spirego.com')
    ) AS map(destination_name, manager_email)
    JOIN "Destinations" d ON d."Name" = map.destination_name
    JOIN "Users" u ON u."Email" = map.manager_email
)
UPDATE "Users" u
SET "ManagedDestinationId" = m.destination_id
FROM spain_expansion_manager_assignments m
WHERE u."Id" = m.manager_id;

