FROM "Destinations" d
WHERE l."DestinationId" = d."Id"
  AND d."Name" IN ('Alicante', 'San Sebastian', 'Girona', 'Cadiz', 'Murcia', 'Santander', 'Tenerife', 'Santiago de Compostela')
  AND d."ManagedByUserId" IS NOT NULL;

