INSERT INTO "Images" ("Url", "AltText", "IsMain", "EventId", "CreatedAt")
SELECT
    s."Url",
    s."AltText",
    s."IsMain",
    e."Id",
    NOW()
FROM source s
JOIN "Events" e ON e."Name" = s."EventName";

