INSERT INTO "Reviews" ("UserId", "ObjectId", "Rating", "Text", "Status", "CreatedAt")
VALUES
((SELECT "Id" FROM "Users" WHERE "Email" = 'bianca.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Hotel Artemide Rome'), 3, 'Hotel je dobro pozicioniran, ali mi soba nije bila dovoljno mirna za duži boravak.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'valentina.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Rione 13 Trastevere'), 4, 'Večera je bila ukusna i atmosfera prijatna, mada bih volela malo bolju organizaciju oko rezervacija.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'marco.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Hotel Canaletto Venice'), 2, 'Lokacija jeste dobra, ali soba je delovala zastarelo i odnos cene i kvaliteta nije najbolji.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'bianca.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Bistrot de Venise'), 5, 'Hrana, vino i usluga su bili na vrlo visokom nivou, bez osećaja žurbe tokom večere.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'riccardo.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Hotel Davanzati Florence'), 2, 'Hotel ima šarm, ali mi komfor sobe nije bio na nivou ocene koju sam očekivao.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'federico.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'La Loggia Firenze'), 4, 'Pogled i ambijent su odlični, iako neka jela nisu baš jednako dobra kao atmosfera.', 'Approved', NOW()),

((SELECT "Id" FROM "Users" WHERE "Email" = 'bianca.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Hotel Lungomare Bari'), 4, 'Dobra lokacija za šetnju uz obalu, a soba je bila sasvim korektna za kraći boravak.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'federico.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Trattoria Bari Vecchia'), 5, 'Hrana je imala domaći ukus, porcije su bile dobre i usluga je bila opuštena.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'valentina.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Galerija Svetog Nikole Bari'), 2, 'Postavka ima zanimljive delove, ali mi je obilazak delovao nedovoljno jasno organizovan.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'bianca.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Centro Bari Galleria'), 4, 'Praktično mesto za kupovinu, sa boljim izborom nego što sam očekivala.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'riccardo.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Hospital Adriatico Bari'), 2, 'Osoblje je bilo korektno, ali čekanje i organizacija prijema su ozbiljno pokvarili utisak.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'marco.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Repsol Lungomare Bari'), 3, 'Pumpa je korisna zbog lokacije, ali prodavnica i usluga nisu ostavile poseban utisak.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'valentina.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Suvenirnica Bari Vecchia'), 5, 'Lep izbor sitnica za poklone i prijatna atmosfera bez previše nametljive prodaje.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'riccardo.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Klinika San Nicola Bari'), 4, 'Pregled je prošao uredno, a osoblje je delovalo smireno i profesionalno.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'federico.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Q8 Porto Bari'), 1, 'Lokacija jeste praktična, ali usluga je bila spora i prostor nije delovao uredno.', 'Approved', NOW()),

((SELECT "Id" FROM "Users" WHERE "Email" = 'bianca.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Hotel Quattro Canti Palermo'), 4, 'Lokacija je odlična za obilazak Palerma, ali bi sobe morale biti bolje izolovane.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'valentina.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Osteria Ballaro Palermo'), 3, 'Hrana je ukusna, ali gužva i tempo usluge nisu baš odgovarali opuštenoj večeri.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'riccardo.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Muzej Normanske Palate Palermo'), 5, 'Obilazak je bio sadržajan, a najviše mi se dopalo što prostor ima jak istorijski karakter.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'federico.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Mercato Palermo Centrale'), 2, 'Ima zanimljivih tezgi, ali je prostor bio naporan za snalaženje i previše haotičan.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'chiara.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Hospital Palermo Centro'), 4, 'Usluga je bila korektna i dobila sam potrebne informacije, iako se čekalo duže.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'marco.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Eni Mondello Palermo'), 2, 'Pumpa je na korisnom mestu, ali nije delovala dovoljno organizovano u gužvi.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'valentina.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Suvenirnica Ballaro Palermo'), 3, 'Ponuda je solidna, ali dosta artikala deluje slično kao u okolnim radnjama.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'riccardo.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Poliklinika Mondello Palermo'), 5, 'Organizacija je bila bolja nego što sam očekivao i sve je završeno bez nervoze.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'marco.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Q8 Foro Italico Palermo'), 1, 'Čekanje je bilo predugo, a prostor nije ostavio utisak dobre održavanosti.', 'Approved', NOW()),

((SELECT "Id" FROM "Users" WHERE "Email" = 'valentina.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Hotel Piazza Unita Trieste'), 5, 'Hotel je odličan za gradski odmor, posebno zbog blizine trga i šetališta.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'federico.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Ristorante Canal Grande Trieste'), 3, 'Ambijent je lep, ali hrana nije bila dovoljno ujednačena za jaču ocenu.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'marco.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Muzej Morskog Trsta'), 2, 'Tema je zanimljiva, ali mi je postavka delovala previše statično.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'riccardo.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Mercato Canal Grande Trieste'), 5, 'Dobar izbor, pregledan prostor i odlična lokacija za kratku kupovinu.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'chiara.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Hospital Porto Trieste'), 2, 'Osnovna usluga je završena, ali proces je bio sporiji nego što bi trebalo.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'valentina.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Eni Miramare Trieste'), 4, 'Praktična pumpa za kratku pauzu, sa korektnom prodavnicom i urednim prostorom.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'bianca.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Suvenirnica Piazza Unita'), 5, 'Izbor suvenira je bolji nego što sam očekivala, a lokacija je baš zgodna.', 'Approved', NOW()),

((SELECT "Id" FROM "Users" WHERE "Email" = 'valentina.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Apartmani Sassi Matera'), 3, 'Smeštaj ima zanimljiv karakter, ali udobnost nije potpuno pratila cenu.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'riccardo.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Osteria Kamena Matera'), 5, 'Večera je bila odlična, sa dobrim ukusima i prijatnom uslugom.', 'Approved', NOW()),
((SELECT "Id" FROM "Users" WHERE "Email" = 'bianca.italy.tourist@spirego.com'), (SELECT "Id" FROM "Objects" WHERE "Name" = 'Muzej Pecinskih Kuca Matera'), 4, 'Muzej lepo objašnjava lokalni kontekst i vredi ga obići ako ste već u Materi.', 'Approved', NOW()),
